def remove_replica(test_tup):
    """Write a function to remove tuple elements that occur more than once and replace the duplicates with some custom value."""
    seen = []
    result = []
    for item in test_tup:
        if item in seen:
            result.append('MSP')
        else:
            seen.append(item)
            result.append(item)
    return tuple(result)
